#!/usr/bin/env python3
"""Emit independently encoded, one-picture HEVC startup streams for Iris.

Encoded with libx265 from a gray 8128x4096 image at 60 fps, Main/Main 10,
keyint=60:repeat-headers=1, with encoder-identification SEI removed. Each
stream contains its own VPS/SPS/PPS and IDR. Compression only keeps the
source distribution small; the generated header contains ordinary Annex B.
"""

import base64
import hashlib
from pathlib import Path
import sys
import zlib

STREAMS = {
    8: (
        "8a10f2f99781dc9aa7b238af4ef8fd9afddc573105f487c2ffc237b7eb2d722e",
        "",
    ),
    10: (
        "12b400f94bdc11168c5706ec31409d9242e74369ac1ea4fcc590238a78034110",
        "",
    ),
}


def main():
    output = ["/* Generated by packaging/frame/iris_bootstrap.py. */"]
    for depth, (digest, encoded) in STREAMS.items():
        data = zlib.decompress(base64.b64decode(encoded))
        if hashlib.sha256(data).hexdigest() != digest:
            raise ValueError(f"Invalid {depth}-bit startup stream")
        output.append(f"static const uint8_t iris_bootstrap_{depth}[] = {{")
        for offset in range(0, len(data), 16):
            output.append("    " + ", ".join(f"0x{x:02x}" for x in data[offset:offset + 16]) + ",")
        output.append("};")
    Path(sys.argv[1]).write_text("\n".join(output) + "\n")


if __name__ == "__main__":
    main()
